visitor._register_domain(INCLUDE_TAG) do |_, val|
  include_path = path.parent.join(val)
  if self.class.glob_pattern?(include_path)
    Dir.glob(include_path.to_s).sort.map { |p| load(Pathname.new(p)) }
       .flat_map { |r| r.is_a?(Array) ? r : [r] }
  else
    load(include_path)
  end
end
